export CHECKPOINT_SKIP="read schema"; python3 -c "
import json;s=json.load(open('schemas/experiment-protocol.v1.json'))
print(json.dumps(s['properties']['analysis_plan'],indent=1)[:1500]); print(json.dumps(s['properties']['freeze'],indent=1)[:800])"; grep -n "frozen_before_data\|script\b\|\"script\"" tools/experiment_protocol.py | head

export CHECKPOINT_SKIP="commit before freeze, no data"; D=docs/reports/2026-11-06-degree-three-module-rss-rerun; git add $D .github/workflows/formal-module-rss.yml && git commit -q -m "formal: protocol, scripts and workflow for the degree-three module RSS rerun (draft, no data)

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01TCbLH96YZo1MqJwSbL3XNg" && python3 tools/experiment_protocol.py freeze $D/protocol.json --filed-before-affected-data 2>&1 | tail -3; python3 -c "import json;print(json.load(open('$D/protocol.json'))['freeze'])"; python3 tools/experiment_protocol.py validate $D/protocol.json | tail -1

export CHECKPOINT_SKIP="building export from collected CI data, no run"; D=docs/reports/2026-11-06-degree-three-module-rss-rerun; python3 -c "
import json;e=json.load(open('$D/export.json'))
for k in ('analysis','host','source','producer','files','flow','notes','backend'): print(k, json.dumps(e[k])[:300])
print(json.dumps(e['runs'][0])[:600])"; python3 -c "
import json;s=json.load(open('schemas/experiment-export.v1.json'));print(json.dumps(s['properties']['analysis'],indent=0)[:900]);print(json.dumps(s['properties']['host'],indent=0)[:700])"

F=/tmp/claude-0/-home-user-crypto-autoresearcher/07fcda66-83c3-5bc6-99e7-f81af94fa447/scratchpad/rlim/fixtures.json; H=$(printf '0%.0s' $(seq 64)); for V in 3000000 2000000 1500000 1000000 700000 500000; do S=$(mktemp -d); mkdir -p $S/r $S/shared; cp $F $S/shared/fixtures.json; ( ulimit -v $V; CHECKPOINT_SKIP="rlimit confirmation on a trivial cell, scratch dir, not an experiment run" timeout 180 python3 experiments/EXP-SEMBIN-cb5e25/code/adapter.py --run-dir $S/r --shared-run-dir $S/shared --kind trial --cell m3n03 --arm EQS4 --r 0 --protocol-sha256 $H >/dev/null 2>$S/err.txt ); ex=$?; chk=$(python3 experiments/EXP-SEMBIN-cb5e25/code/check_trial.py $S/r --shared-run-dir $S/shared 2>&1 | tail -1 | cut -c1-260); rowst=$(python3 - <<E
import json,glob
fs=glob.glob('$S/shared/trials/*.json')
if not fs: print('no trial record')
else:
    d=json.load(open(fs[0])); print('status',d.get('status'),'rows',[ (r.get('status'),r.get('M1',{}).get('contained') if isinstance(r.get('M1'),dict) else None) for r in d.get('rows',d.get('closures',[]))][:3])
E
); echo "V=${V}kB adapter_exit=$ex | $rowst | $chk"; tail -1 $S/err.txt | cut -c1-140; rm -rf $S; done
